Review this iOS 16 SwiftUI + MVVM login change. The diff also adds `NSAppTransportSecurity` with `NSAllowsArbitraryLoads = true` to Info.plist "for the staging server":
```swift
import LocalAuthentication
import os
@MainActor final class LoginViewModel: ObservableObject {
  private let logger = Logger(subsystem: "nl.example.app", category: "auth")
  @Published var isLoggedIn = false
  func didLogin(token: String, refreshToken: String) {
    UserDefaults.standard.set(token, forKey: "accessToken")
    UserDefaults.standard.set(refreshToken, forKey: "refreshToken")
    logger.info("Logged in with token \(token, privacy: .public)")
    isLoggedIn = true
  }
  func unlock() async {
    let context = LAContext()
    let ok = (try? await context.evaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, localizedReason: "Unlock")) ?? false
    if ok, UserDefaults.standard.string(forKey: "refreshToken") != nil { isLoggedIn = true }
  }
}
```

