```swift
import UIKit
import WebKit
import os

final class TokenStore {
  func save(_ token: String) {
    let query: [String: Any] = [kSecClass as String: kSecClassGenericPassword, kSecAttrAccount as String: "session"]
    SecItemDelete(query as CFDictionary)
    var add = query
    add[kSecValueData as String] = Data(token.utf8)
    SecItemAdd(add as CFDictionary, nil)
  }
  func read() -> String? { /* SecItemCopyMatching for the same query, unchanged in this diff */ }
}

// Opened from the custom URL scheme nlexample://help?page=<url>
final class HelpViewController: UIViewController, WKScriptMessageHandler {
  private let logger = Logger(subsystem: "nl.example.app", category: "help")
  private let tokenStore: TokenStore
  private let email: String
  private lazy var webView: WKWebView = {
    let config = WKWebViewConfiguration()
    config.userContentController.add(self, name: "getToken")
    return WKWebView(frame: .zero, configuration: config)
  }()
  init(tokenStore: TokenStore, email: String) { self.tokenStore = tokenStore; self.email = email; super.init(nibName: nil, bundle: nil) }
  required init?(coder: NSCoder) { fatalError() }

  func open(page: URL) {
    logger.info("Opening help for \(self.email)")
    webView.load(URLRequest(url: page))
  }

  func userContentController(_ controller: WKUserContentController, didReceive message: WKScriptMessage) {
    guard message.name == "getToken" else { return }
    webView.evaluateJavaScript("receiveToken('\(tokenStore.read() ?? "")')")
  }
}
```
